#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	// UPROPERTY so GC keeps it alive; raw pointer was collected after ~1 min in packaged build.
	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "AArenaGameMode::ScoreTracker is a raw UObject pointer without UPROPERTY, so the garbage collector does not see the reference and destroys the UArenaScoreTracker at a GC pass (~1 min); OnGoalScored then calls AddPoints on a dangling pointer (EXCEPTION_ACCESS_VIOLATION in UArenaScoreTracker::AddPoints). Fix: UPROPERTY() TObjectPtr<UArenaScoreTracker>.",
  "no_colors_cause": "The palette asset /Game/Data/Palettes/DA_Primary is only loaded by string path via LoadObject, so the cooker never finds a hard reference and does not cook it (only /Game/Maps/Arena and /Game/Data/Effects are cooked). In the packaged build LoadObject returns null and the HUD falls back to gray. Fix: add /Game/Data/Palettes to DirectoriesToAlwaysCook."
}
